questionvariables.text:
/* Generate Pythagorean triple variables */
m : 2 + rand(15);
n : 1 + rand(m-1);

/* Dimensions of the Rhombus (Half diagonals and side) */
a : m^2 - n^2; 
b : 2*m*n ;  
c : m^2 + n^2; 

Perimeter : c * 4; 
One_diagonal : a * 2; 
other_diagonal : b * 2;
Area_of_Rhombus : (One_diagonal * other_diagonal) / 2;

/* Mistakes */
m_half_diag : b; /* Forgot to multiply half-diagonal by 2 */
area_1 : One_diagonal * other_diagonal; /* Forgot to divide by 2 for area */
